//! 🔺️ delete-camera leaf-owned typed sparse operation diff.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfCamera;
use crate::artifacts::gltf::schema::diff::GltfDiff;
use crate::artifacts::gltf::schema::mutations::delete_camera::mutation::{apply, validate, GltfDeleteCameraPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{cameras_op, family_diff, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.delete-camera.v1";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfDeleteCameraOperation { Insert { position: usize, item: GltfCamera }, Delete { index: usize, removed: GltfCamera }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfDeleteCameraDiff { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfDeleteCameraPayload, pub operation: GltfDeleteCameraOperation }
fn operation(payload: &GltfDeleteCameraPayload, base: &GltfSnapshot) -> GltfDeleteCameraOperation { GltfDeleteCameraOperation::Delete { index: payload.index, removed: base.document.cameras[payload.index].clone() } }
fn touched_paths(payload: &GltfDeleteCameraPayload) -> Vec<String> { vec![format!("document/cameras/{}", payload.index)] }
pub fn validate_diff(diff: &GltfDeleteCameraDiff, base: &GltfSnapshot) -> Result<(), GltfTopLevelMutationRejection> { if diff.id != ID || diff.version != 1 { return Err(reject("gltf.mutation.invalid-diff-envelope", "diff", "descriptor identity does not match")); } if diff.touched_paths != touched_paths(&diff.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "diff/touchedPaths", "paths must be concrete payload-derived locations")); } validate(&diff.payload, base)?; if diff.operation != operation(&diff.payload, base) { return Err(reject("gltf.mutation.invalid-sparse-operation", "diff/operation", "operation must equal the direct typed delta")); } Ok(()) }
pub fn apply_diff(diff: &GltfDeleteCameraDiff, base: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_diff(diff, base)?; let mut next = base.clone(); let operation = &diff.operation; match operation { GltfDeleteCameraOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Cameras, &Change::Insert(*position))?; next.document.cameras.insert(*position, item.clone());  }, GltfDeleteCameraOperation::Delete { index, .. } => { cameras_op(&mut next, GltfTopLevelFamily::Cameras, *index, None, None)?;  }, GltfDeleteCameraOperation::Move { index, position } => { cameras_op(&mut next, GltfTopLevelFamily::Cameras, *index, Some(*position), None)?;  }, GltfDeleteCameraOperation::Reorder { order } => { cameras_op(&mut next, GltfTopLevelFamily::Cameras, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(diff: &GltfDeleteCameraDiff) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(diff).map_err(|error| reject("gltf.mutation.encode-failed", "diff", error.to_string())) }
pub fn derive(payload: &GltfDeleteCameraPayload, base: &GltfSnapshot) -> Result<GltfDeleteCameraDiff, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfDeleteCameraDiff { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
pub fn derive_transitional_gltf_diff(payload: &GltfDeleteCameraPayload, base: &GltfSnapshot) -> Result<GltfDiff, GltfTopLevelMutationRejection> { let next = apply(payload, base)?; Ok(family_diff(GltfTopLevelFamily::Cameras, base, &next)) }
